-- 원본 거래·예산·관계자는 보존한다. 과거 거래의 계정을 추정하지 않는다.
ALTER TABLE FINANCIAL_RECORD ADD COLUMN CANCELLED BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE CONTACT ADD COLUMN CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL;
CREATE TABLE ACCT_ACCOUNT(ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,CODE VARCHAR(30) NOT NULL UNIQUE,NAME VARCHAR(100) NOT NULL,TYPE VARCHAR(20) NOT NULL CONSTRAINT CK_ACCT_ACCOUNT_TYPE CHECK(REGEXP_LIKE(TYPE,'^(ASSET|LIABILITY|EQUITY|INCOME|EXPENSE)$')),ACTIVE BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO ACCT_ACCOUNT(CODE,NAME,TYPE) VALUES
('1000','현금','ASSET'),('1100','보통예금','ASSET'),('1200','기타예금','ASSET'),('1300','미수금','ASSET'),('1900','기타자산','ASSET'),
('2000','미지급금','LIABILITY'),('2100','예수금','LIABILITY'),('2200','차입금','LIABILITY'),('2900','기타부채','LIABILITY'),
('3000','기본순자산','EQUITY'),('3100','이월잉여금','EQUITY'),('3200','당기잉여금','EQUITY'),
('4000','헌금수익','INCOME'),('4900','기타수익','INCOME'),
('5000','사역비','EXPENSE'),('5100','예배비','EXPENSE'),('5200','선교비','EXPENSE'),('5300','교육비','EXPENSE'),('5400','관리비','EXPENSE'),('5500','인건비','EXPENSE'),('5900','기타비용','EXPENSE');
CREATE TABLE OFFERING_TYPE(ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,NAME VARCHAR(100) NOT NULL UNIQUE,ACTIVE BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO OFFERING_TYPE(NAME) VALUES('주정헌금'),('약정헌금'),('감사헌금'),('선교헌금'),('절기헌금'),('특별헌금'),('기타헌금');
CREATE TABLE ACCT_ENTRY(ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ENTRY_DATE DATE NOT NULL,FISCAL_YEAR_ID BIGINT NOT NULL REFERENCES FISCAL_YEAR(ID),MEMO VARCHAR(500),SOURCE_RECORD_ID BIGINT REFERENCES FINANCIAL_RECORD(ID),REVERSES_ID BIGINT UNIQUE REFERENCES ACCT_ENTRY(ID),CREATED_AT TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ACCT_LINE(ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ENTRY_ID BIGINT NOT NULL REFERENCES ACCT_ENTRY(ID),ACCOUNT_ID BIGINT NOT NULL REFERENCES ACCT_ACCOUNT(ID),DEBIT BIGINT NOT NULL CHECK(DEBIT>=0),CREDIT BIGINT NOT NULL CHECK(CREDIT>=0),CHECK((DEBIT>0 AND CREDIT=0) OR (CREDIT>0 AND DEBIT=0)));
CREATE INDEX IX_ACCT_ENTRY_DATE ON ACCT_ENTRY(ENTRY_DATE);
CREATE INDEX IX_ACCT_LINE_ACCOUNT ON ACCT_LINE(ACCOUNT_ID,ENTRY_ID);
CREATE TABLE ACCT_LINK(RECORD_ID BIGINT PRIMARY KEY REFERENCES FINANCIAL_RECORD(ID),ENTRY_ID BIGINT REFERENCES ACCT_ENTRY(ID),STATUS VARCHAR(20) NOT NULL,ASSET_ID BIGINT REFERENCES ACCT_ACCOUNT(ID),COUNTERPART_ID BIGINT REFERENCES ACCT_ACCOUNT(ID),OFFERING_TYPE_ID BIGINT REFERENCES OFFERING_TYPE(ID));
INSERT INTO ACCT_LINK(RECORD_ID,STATUS) SELECT ID,'REVIEW' FROM FINANCIAL_RECORD;
CREATE TABLE OFFERING_ALLOCATION(RECORD_ID BIGINT NOT NULL REFERENCES FINANCIAL_RECORD(ID),CONTACT_ID BIGINT NOT NULL REFERENCES CONTACT(ID),AMOUNT BIGINT NOT NULL CHECK(AMOUNT>=0),PRIMARY KEY(RECORD_ID,CONTACT_ID));
CREATE TABLE FINANCE_PREFERENCE(KEY_NAME VARCHAR(60) PRIMARY KEY,VALUE_TEXT VARCHAR(1000));
INSERT INTO FINANCE_PREFERENCE VALUES('PUBLIC_ENABLED','false');
